using System.Collections.Generic;
using UnityEngine;

namespace Astrea.GameElements;

[CreateAssetMenu(fileName = "DiceActionLogic_RandomEnemy", menuName = "Data/Battle/Logics/Dice Action/Random Enemy Dice")]
public class DiceActionLogic_RandomEnemy : DiceActionLogic
{
	[Header("Units")]
	[SerializeField]
	private CurrentCorruptedAnimals currentCorruptedAnimals;

	public override void ActionGrabbed()
	{
		base.ActionGrabbed();
		List<GameObject> list = new List<GameObject>();
		List<GameObject> activeCorruptedAnimals = currentCorruptedAnimals.activeCorruptedAnimals;
		list.Add(activeCorruptedAnimals.PickRandom());
		actionGameState.SetTargetOnActions(list);
		actionGameState.SetHighlightTargetOnActions(activeCorruptedAnimals);
	}
}
